fn check(r:&Rns,input:&[BigInt;4],mode:u8,ipm:&BigInt,minv:&BigInt,expected_costs:&[Cost;3])->BigInt{let s=input.each_ref().map(|x|r.state(x));let mut cc=Cost::default();let z=r.apply(&s[0],&s[1],&s[2],&s[3],mode,true,&mut cc);assert_eq!(cc,expected_costs[mode as usize]);let integer=r.integer(&z);assert!(integer>=BigInt::zero()&&integer<3u32*&r.p);
    let mut t=&input[0]*&input[1];if mode==1{t+=&input[2]*&input[3];}if mode==2{t=t-&input[2]*&input[3]+64u32*&r.p*&r.p;}assert!(t>=BigInt::zero()&&t<128u32*&r.p*&r.p);
    let q=rem(-&t*ipm,&r.left.product);let canonical=(&t+q*&r.p)/&r.left.product;assert_eq!(integer,canonical);assert_eq!(rem(&integer*minv,&r.p),rem(t*minv*minv,&r.p));integer
}
